// Spec 052 B (K8I-002, AC-B1–B3, AC-N3, D-052-01, D-052-03): K8 `interspacoj` on the stored facts
// of fixtures rendered from real M-1 markup and of the counter-probes of D-052-01 (generated by
// `test/k8/generi.mjs`, D-95; this test is pure).
//
// - `anmelden-m1` (the M-1 fragment, unchanged) and `konto-m1` (without the heading of the
//   attribute list, Rest C) must be 1 in every brand × scheme: red before the fixes (A: the empty
//   notices of fm-sxelo; B: the light-DOM pairs of fm-pagxo measured across its slots).
// - The counter-probes stay < 1 where D-052-01 says so, and the Agent's own distributing
//   containers never yield a `verteilita` pair. On the state before the fix they are green (the old
//   measurement measures everything), so each has a self-test: a loosened copy of its facts – every
//   pair marked `verteilita` – must fail its expectation (pattern of zwilling.test.ts (3)).
// - `k8()` equals the stored `atendo.json` (the generator's reference computation) byte for byte.

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { loadModelo, type Modelo, projectModeloSource } from "@fundamento/modelo";
import { describe, expect, it } from "vitest";
import { stabilaJson } from "../ablauf/raporto.js";
import type { Facts, Interspaco, Render } from "../facts.js";
import { ASPEKTOJ, SCHEMES } from "../render.js";
import { AUF_STUFO, k8 } from "./k8.js";

const CXIUJ_CONFIG = fileURLToPath(
  new URL(
    "../../../modelo/test/fixtures/valid/aspekto-provo-kompakta/fundamento.cxiuj.config.json",
    import.meta.url,
  ),
);
const { modelo: ladita } = loadModelo(projectModeloSource(CXIUJ_CONFIG));
if (ladita === undefined) throw new Error("the cxiuj-config Modelo must load");
const modelo: Modelo = ladita;

const legi = (nomo: string, dosiero: string): string =>
  readFileSync(
    fileURLToPath(new URL(`../../test/fixtures/k8/${nomo}/${dosiero}`, import.meta.url)),
    "utf8",
  );

type Aspekto = (typeof ASPEKTOJ)[number];

/** A counter-probe of D-052-01: the brands it must stay < 1 in, and whether pairs may be verteilita. */
interface Gegenprobe {
  nomo: string;
  /** What it stands for (D-052-01, technische Spec B 2/3/3a/3b/3c). */
  kio: string;
  markoj: readonly Aspekto[];
  senVerteilita: boolean;
}

const GEGENPROBOJ: readonly Gegenprobe[] = [
  {
    nomo: "gegenprobe-a-eigener-abstand",
    kio: "(a) own margin-block-start: 13px between two siblings in fm-stako",
    markoj: ASPEKTOJ,
    senVerteilita: false,
  },
  {
    nomo: "gegenprobe-b-doppelte-luecke",
    kio: "(b) the old fm-sxelo fault rebuilt: an empty flex item between two gaps",
    markoj: ["provo", "provo-kompakta"],
    senVerteilita: false,
  },
  {
    nomo: "gegenprobe-c-eigener-verteiler",
    kio: "(c) own <div style=display:flex; justify-content: space-between>",
    markoj: ASPEKTOJ,
    senVerteilita: true,
  },
  {
    nomo: "gegenprobe-d1-eigene-klasse",
    kio: "(d1) own <style> with a class on an own div",
    markoj: ASPEKTOJ,
    senVerteilita: true,
  },
  {
    nomo: "gegenprobe-d2-part",
    kio: "(d2) own <style> fm-pagxo::part(head) { justify-content: space-evenly }",
    markoj: ASPEKTOJ,
    senVerteilita: true,
  },
  {
    nomo: "gegenprobe-3c-ero-mit-style",
    kio: "(3c) an fm-* element with own style justify-content: space-between, itself the container",
    markoj: ASPEKTOJ,
    senVerteilita: true,
  },
];

const M1 = ["anmelden-m1", "konto-m1"] as const;
const NOMOJ = [...M1, ...GEGENPROBOJ.map((g) => g.nomo)];

const fiksajxoj = new Map(
  NOMOJ.map((nomo) => [
    nomo,
    { faktoj: JSON.parse(legi(nomo, "faktoj.json")) as Facts, atendo: legi(nomo, "atendo.json") },
  ]),
);

function faktojDe(nomo: string): Facts {
  const fiksajxo = fiksajxoj.get(nomo);
  if (fiksajxo === undefined) throw new Error(`no fixture ${nomo}`);
  return fiksajxo.faktoj;
}

/** The renders with K8 facts (contrast default), one per brand × scheme of the renderer. */
const k8Renders = (faktoj: Facts) =>
  faktoj.renders.filter(
    (render): render is Render & { k8: NonNullable<Render["k8"]> } =>
      render.contrast === "default" && render.k8 !== undefined,
  );

const KOMBINACIOJ = ASPEKTOJ.length * SCHEMES.length;

/** `interspacoj` of every combination, as "aspekto/scheme" → value. */
function interspacojDe(faktoj: Facts): Record<string, number> {
  const rezulto = k8(faktoj, modelo);
  if (rezulto === undefined) throw new Error("the fixture carries K8 facts");
  return Object.fromEntries(
    rezulto.kombinacioj.map((k) => [`${k.aspekto}/${k.scheme}`, k.merkmaloj.interspacoj]),
  );
}

/** The spacing steps of one render, from its probes (px). */
const stupojDe = (render: Render & { k8: NonNullable<Render["k8"]> }): number[] =>
  render.k8.sondoj
    .filter((sondo) => sondo.eco === "spacing")
    .map((sondo) => Number.parseFloat(sondo.valoro))
    .filter((px) => Number.isFinite(px));

const surStupo = (px: number, stupoj: readonly number[]) =>
  stupoj.some((stupo) => Math.round(Math.abs(px - stupo) * 100) / 100 <= AUF_STUFO);

/** Every combination of the renderer: `interspacoj` = 1 (red findings name the others). */
function cxieUnu(nomo: string): string[] {
  const valoroj = interspacojDe(faktojDe(nomo));
  const malobservoj = Object.entries(valoroj)
    .filter(([, valoro]) => valoro !== 1)
    .map(([kie, valoro]) => `${nomo} ${kie}: interspacoj ${valoro}`);
  if (Object.keys(valoroj).length !== KOMBINACIOJ)
    malobservoj.push(`${nomo}: ${Object.keys(valoroj).length} combinations, not ${KOMBINACIOJ}`);
  return malobservoj;
}

/** The expectation of a counter-probe on facts; empty when it holds. */
function pruefi(gegenprobe: Gegenprobe, faktoj: Facts): string[] {
  const malobservoj: string[] = [];
  const valoroj = interspacojDe(faktoj);
  for (const aspekto of gegenprobe.markoj)
    for (const scheme of SCHEMES) {
      const valoro = valoroj[`${aspekto}/${scheme}`];
      if (valoro === undefined) malobservoj.push(`${aspekto}/${scheme}: not rendered`);
      else if (valoro >= 1)
        malobservoj.push(`${aspekto}/${scheme}: interspacoj ${valoro}, not < 1`);
    }
  if (gegenprobe.senVerteilita) {
    const verteilitaj = k8Renders(faktoj).flatMap((render) =>
      render.k8.interspacoj
        .filter((interspaco) => interspaco.verteilita !== undefined)
        .map(
          (interspaco) =>
            `${render.aspekto}/${render.scheme}: pair ${interspaco.antaux} → ${interspaco.post} verteilita (${interspaco.verteilita?.ero})`,
        ),
    );
    malobservoj.push(...verteilitaj);
  }
  return malobservoj;
}

/** The loosening the self-tests use: every pair marked verteilita by an Ero „fm-x“. */
function malstrecxita(faktoj: Facts): Facts {
  const kopio = structuredClone(faktoj);
  for (const render of k8Renders(kopio))
    render.k8.interspacoj = render.k8.interspacoj.map(
      (interspaco): Interspaco => ({ ...interspaco, verteilita: { ero: "fm-x" } }),
    );
  return kopio;
}

describe("Spec 052 AC-N3: the M-1 markup is 1 in every brand × scheme", () => {
  it("anmelden-m1 (M-1 F anmelden, unchanged): interspacoj = 1 in all combinations", () => {
    expect(cxieUnu("anmelden-m1")).toEqual([]);
  });

  it("konto-m1 (M-1 F konto without the heading, Rest C): interspacoj = 1 in all combinations", () => {
    expect(cxieUnu("konto-m1")).toEqual([]);
  });

  it("konto-m1: no pair over 100 px that is not verteilita", () => {
    const grandaj = k8Renders(faktojDe("konto-m1")).flatMap((render) =>
      render.k8.interspacoj
        .filter((interspaco) => interspaco.px > 100 && interspaco.verteilita === undefined)
        .map(
          (interspaco) =>
            `${render.aspekto}/${render.scheme}: ${interspaco.antaux} → ${interspaco.post} ${interspaco.px} px`,
        ),
    );
    expect(grandaj).toEqual([]);
  });

  it("konto-m1: badges → subtitle is measured and lies on a step of its combination (lead)", () => {
    const faktoj = faktojDe("konto-m1");
    const indekso = (slot: string) =>
      faktoj.elements.findIndex((elemento) => elemento.attrs.slot === slot);
    const [badges, subtitle] = [indekso("badges"), indekso("subtitle")];
    expect(badges).toBeGreaterThanOrEqual(0);
    expect(subtitle).toBeGreaterThan(badges);
    const malobservoj: string[] = [];
    const renders = k8Renders(faktoj);
    expect(renders).toHaveLength(KOMBINACIOJ);
    for (const render of renders) {
      const kie = `${render.aspekto}/${render.scheme}`;
      const paro = render.k8.interspacoj.find(
        (interspaco) => interspaco.antaux === badges && interspaco.post === subtitle,
      );
      if (paro === undefined) malobservoj.push(`${kie}: badges → subtitle not measured`);
      else if (paro.verteilita !== undefined)
        malobservoj.push(`${kie}: badges → subtitle verteilita`);
      else if (!surStupo(paro.px, stupojDe(render)))
        malobservoj.push(`${kie}: badges → subtitle ${paro.px} px off every step`);
    }
    expect(malobservoj).toEqual([]);
  });
});

describe("Spec 052 counter-probes of D-052-01 (AC-B2, AC-B3)", () => {
  for (const gegenprobe of GEGENPROBOJ) {
    const kie = `${gegenprobe.markoj.join(", ")}${gegenprobe.senVerteilita ? "; no pair verteilita" : ""}`;
    it(`${gegenprobe.kio}: interspacoj < 1 in ${kie}`, () => {
      expect(pruefi(gegenprobe, faktojDe(gegenprobe.nomo))).toEqual([]);
    });

    it(`${gegenprobe.nomo} self-test: a loosened copy (every pair verteilita) fails the expectation`, () => {
      const faktoj = faktojDe(gegenprobe.nomo);
      const malstrecxitaj = malstrecxita(faktoj);
      // The loosening reaches every pair and leaves the stored facts alone.
      expect(
        k8Renders(malstrecxitaj).every((render) =>
          render.k8.interspacoj.every((interspaco) => interspaco.verteilita?.ero === "fm-x"),
        ),
      ).toBe(true);
      expect(stabilaJson(faktoj)).toBe(legi(gegenprobe.nomo, "faktoj.json"));
      expect(pruefi(gegenprobe, malstrecxitaj)).not.toEqual([]);
    });
  }
});

describe("Spec 052 fixtures: k8() equals atendo.json byte for byte", () => {
  for (const nomo of NOMOJ) {
    it(nomo, () => {
      expect(stabilaJson(k8(faktojDe(nomo), modelo))).toBe(fiksajxoj.get(nomo)?.atendo);
    });
  }
});
